import java.util.PriorityQueue;

class MinHeap {
    private PriorityQueue<Integer> pq = new PriorityQueue<>();

    public void insert(int val) { pq.offer(val); }
    public void removeMin() { pq.poll(); }
    public int minElement() { return pq.isEmpty() ? -1 : pq.peek(); }
}
